public sealed class Products(IMemoryCache cache, IProductStore db)
{
    private readonly Lock _gate = new();

    public async Task<Product?> GetAsync(int id)
    {
        if (cache.TryGetValue(id, out Product? hit)) return hit;
        var p = await db.LoadAsync(id);
        if (p is not null) Offer(p); // an old version loses to a newer one
        return p;
    }

    public async Task SetPriceAsync(int id, decimal price) =>
        Offer(await db.SavePriceAsync(id, price)); // returns the new version

    private void Offer(Product p)
    {
        lock (_gate) // compare and set as one step
        {
            if (cache.TryGetValue(p.Id, out Product? cur)
                && cur!.Version >= p.Version) return; // already as new
            cache.Set(p.Id, p, TimeSpan.FromMinutes(5)); // TTL: the backstop
        }
    }
}
